Exactoo. `->` es "flecha": desreferencia el puntero y accede al campo en un solo paso. Mira ambas versiones comparadas:

```c
#include <stdio.h>
#include <string.h>

struct Empleado {
    int id;
    char nombre[50];
    float salario;
};

/* Paso por VALOR — trabaja sobre fotocopia, no modifica el original */
void actualizarNombreValor(struct Empleado e, char nuevoNombre[]) {
    strcpy(e.nombre, nuevoNombre);   /* modifica la copia, se pierde al salir */
}

/* Paso por REFERENCIA — trabaja sobre la ficha original */
void actualizarNombreRef(struct Empleado *e, char nuevoNombre[]) {
    strcpy(e->nombre, nuevoNombre);  /* modifica el original */
}

int main() {
    struct Empleado emp;
    emp.id = 1;
    strcpy(emp.nombre, "Pedro López");
    emp.salario = 2500.0;

    printf("Antes: %s\n", emp.nombre);

    actualizarNombreValor(emp, "Juan Díaz");
    printf("Después de pasar por valor: %s\n", emp.nombre);  /* sigue siendo Pedro López */

    actualizarNombreRef(&emp, "Juan Díaz");
    printf("Después de pasar por referencia: %s\n", emp.nombre);  /* ahora es Juan Díaz */

    return 0;
}
```

Nota el `&emp` al llamar la función por referencia — pasas la dirección del struct. ¿Ves la diferencia en la salida que produciría?
